import "@testing-library/jest-dom/vitest";
import { afterEach, vi } from "vitest";
import { cleanup } from "@testing-library/react";
import { createElement, type ReactNode } from "react";

afterEach(() => {
  cleanup();
});

// The GitHub snapshot is generated by `npm run sync:github`. Tests must not
// depend on whatever is on the machine, so point the reader at a missing file.
process.env.GITHUB_SNAPSHOT = "/__no-github-snapshot__/github-snapshot.json";

if (typeof window !== "undefined" && !window.matchMedia) {
  window.matchMedia = ((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: () => {},
    removeListener: () => {},
    addEventListener: () => {},
    removeEventListener: () => {},
    dispatchEvent: () => false,
  })) as unknown as typeof window.matchMedia;
}

vi.mock("@/i18n/navigation", () => ({
  Link: ({ href, children, ...props }: { href: string; children: ReactNode }) =>
    createElement(
      "a",
      { href: href.startsWith("/") ? `/en${href}` : href, ...props },
      children,
    ),
  usePathname: () => "/",
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), prefetch: vi.fn() }),
  redirect: vi.fn(),
  getPathname: vi.fn(),
}));
